import React,{useState,useEffect,useRef} from 'react';
import {createRoot} from 'react-dom/client';
import {api,inspect,normal} from './inspection';
import {Pop} from './pop';
import './styles.css';
import './movement.css';
import {PixelWorld} from './World';
import {Intro} from './Intro';
import {useWorkspaceSave} from './useWorkspaceSave';
import {SaveNotice} from './SaveNotice';
import './saving.css';
const KEY='strikeout.v2.local',INTRO='strikeout.pop.intro.v1';
const uid=()=>crypto.randomUUID();
const when=(d:string)=>new Date(d).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
const kinds=['My account was hacked.','Someone is impersonating me.','My personal information is exposed.','I received a suspicious link or message.','I’m not sure.'];
const routes:any={Instagram:{recovery:'https://www.instagram.com/hacked/',report:'https://help.instagram.com/370054663112398'},Facebook:{recovery:'https://www.facebook.com/hacked',report:'https://www.facebook.com/help/174210519303259'},Google:{recovery:'https://accounts.google.com/signin/recovery',report:'https://support.google.com/accounts/answer/6294825'}};
function load(){try{return JSON.parse(localStorage.getItem(KEY)||'{"cases":[],"identifiers":[]}')}catch{return {cases:[],identifiers:[]}}}
function download(name:string,text:string,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function Button({children,secondary=false,className='',...props}:any){return <button className={(secondary?'button secondary':'button')+' '+className} {...props}>{children}</button>}
function Field({label,children,hint}:any){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Note({children,tone='plain'}:any){return <div className={'notice '+tone}>{children}</div>}
function Auth({done,close}:any){const [mode,setMode]=useState('register'),[error,setError]=useState(''),[busy,setBusy]=useState(false);const dialog=useRef<HTMLDivElement>(null);useEffect(()=>{const before=document.activeElement as HTMLElement;dialog.current?.querySelector('input')?.focus();const trap=(e:KeyboardEvent)=>{if(e.key==='Escape')close();if(e.key==='Tab'){const list=Array.from(dialog.current?.querySelectorAll<HTMLElement>('button,input,a')||[]).filter(x=>!x.hasAttribute('disabled'));const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};document.addEventListener('keydown',trap);return()=>{document.removeEventListener('keydown',trap);before?.focus()};},[]);return <div className="modal-backdrop"><div ref={dialog} className="modal" role="dialog" aria-modal="true" aria-labelledby="auth-title"><button className="modal-close" aria-label="Close sign-in" onClick={close}>×</button><div className="eyebrow">YOUR DRAFT IS WAITING RIGHT HERE</div><h2 id="auth-title">{mode==='register'?'Make a little room.':'Welcome back.'}</h2><p>{mode==='register'?'Create a Strikeout account to save cases and keep your evidence together. Your draft stays put.':'Sign in to return to your cases and saved progress.'}</p><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');const f=new FormData(e.currentTarget);try{const x=await api('/api/auth/'+mode,'POST',{username:f.get('username'),password:f.get('password')});await done(x.user);}catch(e:any){setError(e.message)}finally{setBusy(false)}}}><Field label="Strikeout username"><input name="username" autoComplete="username" required minLength={3} maxLength={32} pattern="[A-Za-z0-9_-]+"/></Field><Field label="Strikeout password" hint="10+ characters. Use a new password just for Strikeout. Never enter a social-account password or recovery code."><input name="password" type="password" required minLength={10} maxLength={128} autoComplete={mode==='register'?'new-password':'current-password'}/></Field>{error&&<Note tone="error">{error}</Note>}<Button disabled={busy}>{busy?'Saving your place…':mode==='register'?'Create account & continue →':'Sign in & continue →'}</Button></form><button className="text-button" onClick={()=>{setMode(mode==='register'?'login':'register');setError('')}}>{mode==='register'?'Already have an account? Sign in':'New here? Create an account'}</button><p className="small">This prototype uses synthetic demonstration sources. Account recovery for a forgotten Strikeout password is not available; export your cases before deleting an account.</p></div></div>}
function App(){
 const [path,setPath]=useState(location.pathname),[intro,setIntro]=useState(!localStorage.getItem(INTRO)),[user,setUser]=useState<any>(null),[auth,setAuth]=useState<any>(null),[data,setData]=useState<any>(()=>({cases:[],identifiers:load().identifiers||[]})),[notice,setNotice]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(''),[source,setSource]=useState<any>(null),[ai,setAi]=useState(false),[loaded,setLoaded]=useState(false);
 const [online,setOnline]=useState(navigator.onLine);const saver=useWorkspaceSave(user?.id||null,loaded,data,setData);async function remoteData(owner:string,transfer?:any){return saver.hydrate(owner,await api('/api/data'),transfer);}const cases=data.cases||[],ids=data.identifiers||[];
 const go=(p:string)=>{history.pushState({},'',p);setPath(p);setError('');setNotice('');window.scrollTo(0,0);};
 useEffect(()=>{const fn=()=>setPath(location.pathname);window.addEventListener('popstate',fn);api('/api/auth/me').then(async x=>{setUser(x.user);if(x.user){setData(await remoteData(x.user.id))}}).catch(()=>{}).finally(()=>setLoaded(true));return()=>window.removeEventListener('popstate',fn)},[]);
 useEffect(()=>{try{localStorage.setItem(KEY,JSON.stringify(user?{cases:[],identifiers:[]}:data))}catch{setError('Browser storage is full. Export your case and remove large screenshots.')}},[data,user]);

 useEffect(()=>{const yes=()=>setOnline(true),no=()=>setOnline(false);window.addEventListener('online',yes);window.addEventListener('offline',no);return()=>{window.removeEventListener('online',yes);window.removeEventListener('offline',no)}},[]);
 async function run(label:string,fn:()=>Promise<any>){setBusy(label);setError('');try{return await fn()}catch(e:any){setError(e.message);return null}finally{setBusy('')}}
 async function authenticated(fn:()=>Promise<any>){if(user&&!user.guest)return fn();setAuth(()=>async(u:any)=>{const carry=user?.guest&&user.workspaceId===u.workspaceId?saver.capture():undefined;setLoaded(false);setUser(u);const remote=await remoteData(u.id,carry);setData((local:any)=>({cases:[...remote.cases,...local.cases.filter((c:any)=>!remote.cases.some((r:any)=>r.id===c.id))],identifiers:[...remote.identifiers,...local.identifiers.filter((x:any)=>!remote.identifiers.some((r:any)=>r.id===x.id))]}));setAuth(null);setLoaded(true);await fn();});}
 const currentId=path.split('/')[2],current=cases.find((c:any)=>c.id===currentId),tab=path.split('/')[3]||'story';
 function save(c:any){setData((d:any)=>({...d,cases:d.cases.some((x:any)=>x.id===c.id)?d.cases.map((x:any)=>x.id===c.id?c:x):[c,...d.cases]}));}
 function update(patch:any,event?:string){if(!current)return;save({...current,...patch,updatedAt:new Date().toISOString(),timeline:event?[...(current.timeline||[]),{id:uid(),at:new Date().toISOString(),text:event}]:current.timeline});}
 async function getSource(){const s=await api('/api/source');setSource(s);return s;}
 function sample(){run('Opening fictional sample',async()=>{if(!user){const x=await api('/api/demo/start','POST');setData(await remoteData(x.user.id));setUser(x.user);}const s=await getSource(),at=new Date().toISOString(),c={id:uid(),title:'Mira’s public portfolio',kind:kinds[1],platform:'Instagram',description:'A fictional profile is using my name. My personal number is also visible in my portfolio and résumé. I want to report the profile and remove my number while keeping my work online.',summary:'A fictional profile is reportedly using Mira’s identity. Mira wants help preparing an impersonation report and removing her personal number from supported public material. Her work email and projects should remain public.',profile:s.base+'/impersonation-example',realProfile:'https://example.com/mira',phone:s.profile.phone,country:'US',email:s.profile.email,reviewed:true,evidence:[],timeline:[{id:uid(),at,text:'Fictional sample case opened.'}],createdAt:at};save(c);go('/case/'+c.id+'/story')});}
 useEffect(()=>{if(path==='/sample'&&loaded)sample()},[path,loaded]);
 const finishIntro=()=>{localStorage.setItem(INTRO,'done');setIntro(false)};
 if((intro&&path==='/')||path==='/meet-pop')return <Intro go={go} finish={finishIntro}/>;
 const link=(p:string,text:any,cls='')=><a className={cls} href={p} onClick={e=>{e.preventDefault();go(p)}}>{text}</a>;
 const heading=(eyebrow:string,title:string,desc?:string)=><header className="page-heading"><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{desc&&<p>{desc}</p>}</header>;
 return <div className="website"><a className="skip-content" href="#main">Skip to content</a><header className="site-header">{link('/home',<>STRIKEOUT<span>↗</span></>,'wordmark')}<nav aria-label="Main navigation">{link('/home','Home',path==='/home'||path==='/'?'active':'')}{link('/cases','My cases',path==='/cases'?'active':'')}{link('/meet-pop','Meet Pop',path==='/meet-pop'?'active':'')}<button className="account-link" onClick={()=>user?run('Signing out',async()=>{if(!await saver.flush())throw Error('Your edits still need saving. Review the pending changes before signing out.');await api('/api/auth/logout','POST');setUser(null);setData({cases:[],identifiers:[]});go('/home')}):setAuth(()=>async(u:any)=>{setLoaded(false);setUser(u);setData(await remoteData(u.id));setLoaded(true);setAuth(null)})}>{user?user.username+' · Sign out':'Sign in'}</button>{user?.guest&&<button className="account-link" onClick={()=>authenticated(async()=>{})}>Create account</button>}{user&&<button className={'text-button save-indicator '+(['error','auth','conflict'].includes(saver.state.phase)?'failed':'')} title={saver.state.phase==='conflict'?'Review the pending edits below':'Case save status'} disabled={!['error','offline'].includes(saver.state.phase)} onClick={()=>void saver.retry()} aria-live="polite">{saver.state.message}</button>}</nav></header>{!online&&<div className="offline-banner" role="status">You’re offline. Local case and repair tools still work while this local server is running. Live search and AI need internet.</div>}<div className="demo-ribbon"><span>CONTROLLED DEMONSTRATION</span> Public demo sources use fictional data. Your case is not an official complaint.</div><main id="main" className="route-panel" key={path} tabIndex={-1}>
 {user&&<SaveNotice saver={saver} download={download} signIn={()=>setAuth(()=>async(u:any)=>{setLoaded(false);setUser(u);setData(await remoteData(u.id));setLoaded(true);setAuth(null)})}/>}{error&&<div className="global-message" role="alert"><Note tone="error">{error}<button className="text-button" onClick={()=>setError('')}>Dismiss</button></Note></div>}{notice&&<div className="global-message" role="status"><Note tone="success">{notice}</Note></div>}
 {(path==='/'||path==='/home')&&<><section className="home-hero"><div><div className="eyebrow">A LITTLE LESS OVERWHELMING.</div><h1>Your space.<br/>Your <em>next step.</em></h1><p>Something happened online. Start wherever<br className="desktop"/> you are. We’ll take it one thing at a time.</p></div><div className="home-pop"><PixelWorld home/><div className="world-caption">A SMALL CORNER OF A VERY BIG INTERNET</div><button className="mini-window home-meet-pop" onClick={()=>go('/meet-pop')} aria-label="Meet Pop — play the introduction"><span>MEET YOUR COMPANION ↗</span><Pop state="curious" size={210}/><p>“Okay. One thing at a time.<br/>I’m here.”</p><strong className="meet-pop-prompt">Play Pop’s introduction →</strong></button><div className="tape">YOUR CALL. ALWAYS.</div></div></section><section className="home-actions" aria-label="Where would you like to start?"><button onClick={()=>go('/incident')}><span className="action-no">01</span><span><strong>Log an incident</strong><small>Tell your story. Decide what happens next.</small></span><b>↗</b></button><button onClick={()=>go('/exposure')}><span className="action-no">02</span><span><strong>Check my exposure</strong><small>Look at supported public information, with context.</small></span><b>↗</b></button><button onClick={()=>go('/cases')}><span className="action-no">03</span><span><strong>My cases</strong><small>Your evidence, requests and progress.</small></span><b>↗</b></button></section><section className="home-foot"><p><span className="pixel-label">KEEP YOUR WORK ONLINE.</span><br/>Take your personal number out. {link('/sample','Explore the repair demonstration →')}</p><div>{link('/extension','Get the Pop extension ↗')}<button className="text-button" onClick={()=>go('/meet-pop')}>Replay Pop’s introduction</button></div></section></>}
 {path==='/incident'&&<Incident heading={heading} authenticated={authenticated} save={save} go={go} run={run} busy={busy}/>}
 {path==='/cases'&&<section className="page-wrap">{heading('YOUR PRIVATE WORKSPACE','A place to pick back up.','Cases save your story and next steps in Strikeout. Official submissions happen separately.')}<div className="toolbar"><Button onClick={()=>go('/incident')}>Log an incident →</Button><Button secondary onClick={sample}>Explore a sample case</Button><button className="text-button" onClick={()=>download('strikeout-cases.json',JSON.stringify(data,null,2),'application/json')}>Export my cases</button></div>{cases.length?<div className="case-list">{cases.map((c:any,i:number)=><button key={c.id} onClick={()=>go('/case/'+c.id+'/story')}><span className="action-no">{String(i+1).padStart(2,'0')}</span><div><span className="eyebrow">{c.kind}</span><h2>{c.title}</h2><p>{c.summary?.slice(0,160)||c.description?.slice(0,160)}</p><small>Updated {when(c.updatedAt||c.createdAt)}</small></div><b>↗</b></button>)}</div>:<div className="empty-state"><Pop state="sleeping" size={110}/><h2>A clean page.</h2><p>Start a case, or see how the fictional portfolio repair works.</p></div>}<details className="settings"><summary>Privacy, export and deletion</summary><p>Your existing earlier-version browser vault is left untouched. This version uses a separate storage key. Export cases before deleting an account.</p>{link('/privacy','Read data and privacy details →')}<Button secondary onClick={()=>{if(confirm('Delete all cases saved in this browser? Your signed-in account will also be updated.'))setData((d:any)=>({...d,cases:[]}))}}>Delete my cases</Button>{user&&<Button secondary onClick={()=>{if(confirm('Delete your Strikeout account, saved cases and published demo material? This cannot be undone.'))run('Deleting account',async()=>{await api('/api/account','DELETE');setUser(null);setData({cases:[],identifiers:[]});setNotice('Account, cases and hosted demonstration material deleted.');})}}>Delete account and hosted demo</Button>}</details></section>}
 {path==='/exposure'&&<Discovery heading={heading} user={user} authenticated={authenticated} ids={ids} setIds={(identifiers:any)=>setData((d:any)=>({...d,identifiers}))} go={go} sample={sample} cases={cases} save={save} run={run} busy={busy}/>}
 {path.startsWith('/case/')&&(current?<div className="workspace"><aside className="case-sidebar"><button className="text-button" onClick={()=>go('/cases')}>← All cases</button><span className="eyebrow">YOUR CASE</span><h2>{current.title}</h2><nav aria-label="Case sections">{[['story','Your story'],['evidence','Evidence'],['steps','Next steps'],['requests','Requests'],['progress','Progress']].map(([key,label],i)=>link('/case/'+current.id+'/'+key,<><span>0{i+1}</span>{label}</>,tab===key?'selected':''))}</nav><div className="sidebar-pop"><Pop size={100} state={busy?'inspecting':'idle'}/><p>{busy||'A little progress counts.'}</p></div><small>Only actions you review and choose move this case forward.</small></aside><div className="case-body">
 {tab==='story'&&<>{heading('01 / YOUR STORY','Start with what you know.','You can edit this. Unknown facts can stay unknown.')}<Field label="Incident summary"><textarea rows={6} value={current.summary??current.description} onChange={e=>update({summary:e.target.value,reviewed:false,draftStale:true,preview:null})}/></Field><div className="coverage">Missing or uncertain facts: {![kinds[0],kinds[1]].includes(current.kind)||current.profile?'profile reference supplied':'add the account/profile reference below'} · {current.date?'date supplied':'incident date not specified'}. User-supplied facts are not independently established.</div>{[kinds[0],kinds[1]].includes(current.kind)&&<Field label="Account / reported profile reference"><input value={current.profile||''} onChange={e=>update({profile:e.target.value,draftStale:true,reportReady:false})}/></Field>}<div className="fact-strip"><span><small>TYPE</small>{current.kind}</span><span><small>PLATFORM</small>{current.platform||'Not specified'}</span></div><Field label="Personal number to protect"><input value={current.phone||''} onChange={e=>update({phone:e.target.value,scan:null,preview:null,verification:null,draftStale:true})}/></Field><Field label="Number’s country"><select value={current.country||'IN'} onChange={e=>update({country:e.target.value,scan:null,preview:null,verification:null})}><option value="IN">India (+91)</option><option value="US">US / fictional demonstration (+1)</option><option value="GB">United Kingdom (+44)</option></select></Field><Field label="Work email to preserve"><input type="email" value={current.email||''} onChange={e=>update({email:e.target.value,preview:null,verification:null,draftStale:true})}/></Field><label className="check"><input type="checkbox" checked={!!current.reviewed} onChange={e=>update({reviewed:e.target.checked},e.target.checked?'Incident summary reviewed.':undefined)}/>I have reviewed this summary. It reflects my account of what happened.</label><div className="toolbar"><Button onClick={()=>go('/case/'+current.id+'/steps')}>See my next step →</Button><Button secondary onClick={()=>setAi(true)}>Ask Pop about selected notes</Button></div></>}
 {tab==='evidence'&&<Evidence current={current} update={update} heading={heading} setError={setError}/>}
 {tab==='steps'&&<>{heading('03 / NEXT STEPS','One useful thing at a time.',current.kind===kinds[0]?'Recover through the official platform. Keep your evidence and action notes here.':'Inspect the supported public material, then decide what to change.')}{current.kind===kinds[3]?<LinkCheck current={current}/>:<Official current={current}/>}<Inspection current={current} update={update} source={source} getSource={getSource} run={run} busy={busy} go={go} setNotice={setNotice}/></>}
 {tab==='requests'&&<Requests current={current} update={update} heading={heading} run={run} busy={busy} source={source} getSource={getSource} go={go} setNotice={setNotice}/>}
 {tab==='progress'&&<Progress current={current} update={update} heading={heading} run={run} busy={busy} getSource={getSource} go={go}/>}
 </div></div>:<section className="page-wrap">{heading('CASE NOT IN THIS WORKSPACE','We couldn’t open that case.','Sign in to the account that owns it, or return to your cases.')}<Button onClick={()=>authenticated(async()=>go('/cases'))}>Open my cases →</Button></section>)}
 {path==='/extension'&&<section className="page-wrap extension-page"><div><div className="eyebrow">POP / A SMALL BROWSER COMPANION</div><h1>Same cat.<br/><em>New neighbourhood.</em></h1><p>Inspect a link when you choose. Pop explains observable signals without automatically visiting the destination.</p><Pop size={180} state="walking"/><a className="button" href="/pop-extension.zip" download>Download Pop for Chromium ↓</a><p className="small">Developer-mode package. Not listed in the Chrome Web Store. Downloading does not install or activate it.</p></div><div className="paper"><h2>Bring Pop along.</h2><ol className="install-steps"><li>Download and extract the ZIP into a folder.</li><li>Open <code>chrome://extensions</code> or <code>edge://extensions</code>.</li><li>Enable Developer mode, choose “Load unpacked”, and select that folder.</li><li>Click Pop’s toolbar icon. Choose “Bring Pop to this page” to grant temporary access through your deliberate click.</li></ol><p>Link inspection uses local URL signals. Optional hover help is off until you enable it. No browsing history is collected. Pop never clicks, submits, or opens a suspicious destination for you.</p><Note>Installation and browser permissions happen in your browser. The introduction does not grant them.</Note><button className="text-button" onClick={()=>go('/privacy')}>Permissions and privacy →</button></div></section>}
 {path==='/privacy'&&<section className="page-wrap prose">{heading('PLAIN WORDS, NO FINE-PRINT MAZE','Your data stays your decision.')}<h2>What this prototype stores</h2><p>Drafts are kept in this browser so you can start before signing in. Signed-in cases and selected evidence are saved to private server-side storage, protected by your account session. Demonstration portfolio material is public by design and contains reserved fictional contact data.</p><h2>What it shares</h2><p>A GitHub self-check sends only the selected username to GitHub after approval. Pop’s optional AI sends only the context you review to Google Gemini. Their service policies apply. Neither receives your Strikeout password. Official complaint forms open separately and receive only what you submit there.</p><h2>What it can establish</h2><p>A supported fresh check can establish what was found in the specific retrieved source at that time. It cannot prove identity, inspect private accounts, guarantee takedowns or establish that you are safe across the internet.</p><h2>Export and deletion</h2><p>Export cases in My cases. Delete cases there, or delete your account and hosted demo. Browser downloads, provider records and other people’s copies are not removed by deleting a Strikeout case. Infrastructure providers may retain operational request metadata.</p><h2>Pop extension</h2><p>Permissions: storage for preferences; activeTab and scripting for a page you explicitly choose; contextMenus for deliberate link inspection. Hover assistance is opt-in and reads link labels and destinations only. No passwords, forms, recovery codes or browsing history are collected. Remote reputation checks are not enabled.</p><h2>Before real sensitive use</h2><p>This is a hackathon prototype, not an independently audited incident-response service. Use fictional information for the demonstration. Evidence is not automatically sent to AI or an authority.</p></section>}
 </main><footer className="site-footer"><span className="wordmark small-brand">STRIKEOUT ↗</span><span>Keep your work. Keep your privacy.</span>{link('/privacy','Privacy & scope')}{link('/extension','Pop for your browser')}</footer>{auth&&<Auth close={()=>setAuth(null)} done={auth}/>}<button className="pop-helper" onClick={()=>setAi(true)} aria-label="Open Pop assistant"><Pop size={50} state="curious"/><span>Ask Pop</span></button>{ai&&<AiPanel current={current} close={()=>setAi(false)} authenticated={authenticated}/>}<div className="sr-only" aria-live="polite">{busy}</div></div>
}
function Incident({heading,authenticated,save,go,run,busy}:any){const [draft,setDraft]=useState<any>(()=>{try{if(location.hash.startsWith('#handoff=')){const h=JSON.parse(decodeURIComponent(location.hash.slice(9)));return {kind:kinds[3],link:String(h.link||'').slice(0,500),description:String(h.description||'').slice(0,4000)}}return JSON.parse(localStorage.getItem('strikeout.incident.draft')||'{}')}catch{return {}}});const change=(k:string,v:any)=>{const d={...draft,[k]:v};setDraft(d);localStorage.setItem('strikeout.incident.draft',JSON.stringify(d));};return <section className="page-wrap intake">{heading('YOUR FIRST STEP','What happened?','Start with a few details. You don’t need to have everything figured out.')}<div className="intake-grid"><form className="paper" onSubmit={e=>{e.preventDefault();authenticated(async()=>{const at=new Date().toISOString(),c={...draft,platform:draft.platform||([kinds[0],kinds[1]].includes(draft.kind)?'Instagram':''),id:uid(),title:(draft.platform?draft.platform+' · ':'')+(draft.kind===kinds[0]?'Account access':draft.kind===kinds[1]?'Impersonation':draft.kind===kinds[2]?'Contact exposure':'Online incident'),summary:draft.description,reviewed:false,createdAt:at,evidence:[],timeline:[{id:uid(),at,text:'Case created in Strikeout. No official complaint submitted.'}]};save(c);localStorage.removeItem('strikeout.incident.draft');go('/case/'+c.id+'/story')})}}><Field label="What happened?"><select required value={draft.kind||''} onChange={e=>change('kind',e.target.value)}><option value="">Choose what fits best</option>{kinds.map(k=><option key={k}>{k}</option>)}</select></Field>{draft.kind&&<><Field label="Tell us a little about it" hint="Use only information you’re comfortable saving. Leave unknowns unknown."><textarea rows={5} required maxLength={4000} value={draft.description||''} onChange={e=>change('description',e.target.value)}/></Field>{[kinds[0],kinds[1]].includes(draft.kind)&&<><Field label="Platform"><select value={draft.platform||'Instagram'} onChange={e=>change('platform',e.target.value)}>{Object.keys(routes).map(x=><option key={x}>{x}</option>)}</select></Field><Field label={draft.kind===kinds[0]?'Your account identifier':'Suspected profile URL or identifier'}><input value={draft.profile||''} onChange={e=>change('profile',e.target.value)} maxLength={500}/></Field>{draft.kind===kinds[0]&&<><Field label="Can you still access your account?"><select value={draft.access||'unsure'} onChange={e=>change('access',e.target.value)}><option value="unsure">I’m not sure</option><option value="yes">Yes</option><option value="no">No</option></select></Field><Field label="Can you access your recovery email?"><select value={draft.recovery||'unsure'} onChange={e=>change('recovery',e.target.value)}><option value="unsure">I’m not sure</option><option value="yes">Yes</option><option value="no">No</option></select></Field></>}{draft.kind===kinds[1]&&<Field label="Your real profile (optional)"><input value={draft.realProfile||''} onChange={e=>change('realProfile',e.target.value)}/></Field>}</>}{draft.kind===kinds[2]&&<><Field label="Personal phone number"><input type="tel" value={draft.phone||''} onChange={e=>change('phone',e.target.value)}/></Field><Field label="Source URL (saved as a reference)"><input type="url" value={draft.sourceUrl||''} onChange={e=>change('sourceUrl',e.target.value)}/></Field><Field label="Work email you want to keep (optional)"><input type="email" value={draft.email||''} onChange={e=>change('email',e.target.value)}/></Field></>}{draft.kind===kinds[3]&&<Field label="Suspicious link (not visited)"><input value={draft.link||''} onChange={e=>change('link',e.target.value)}/></Field>}<Field label="When did you notice? (optional)"><input type="date" value={draft.date||''} onChange={e=>change('date',e.target.value)}/></Field><Note>“Log an incident” saves a STRIKEOUT case. It does not file a complaint with a platform, police, or another authority.</Note><Button disabled={!!busy}>Save and continue →</Button></>}</form><aside className="intake-note"><Pop state="concerned" size={140}/><h2>You set the pace.</h2><p>Start with your story. Add evidence when you’re ready. Review anything before it’s shared.</p><p className="small">We never need the password, recovery codes or one-time codes for your social or email accounts.</p></aside></div></section>}
function Evidence({current,update,heading,setError}:any){const [note,setNote]=useState(''),[url,setUrl]=useState(''),[date,setDate]=useState(''),[file,setFile]=useState<any>(null);return <>{heading('02 / EVIDENCE','Keep the useful bits.','Save context once. Choose exactly what belongs in a request later.')}<form className="paper" onSubmit={e=>{e.preventDefault();const item={id:uid(),note,url,date,addedAt:new Date().toISOString(),file};update({evidence:[...(current.evidence||[]),item]},'Evidence added: '+(note.slice(0,80)||url||file?.name));setNote('');setUrl('');setDate('');setFile(null)}}><Field label="What does this show?"><textarea rows={3} required value={note} onChange={e=>setNote(e.target.value)}/></Field><Field label="Source link (optional)"><input type="url" value={url} onChange={e=>setUrl(e.target.value)}/></Field><Field label="Date shown in the evidence (optional)"><input type="date" value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="Optional sample screenshot" hint="PNG or JPEG, maximum 500 KB. Use fictional evidence in this demonstration."><input type="file" accept="image/png,image/jpeg" onChange={e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>500000||!['image/png','image/jpeg'].includes(f.type)){setError('Choose a PNG/JPEG screenshot smaller than 500 KB.');return;}const reader=new FileReader();reader.onload=()=>setFile({name:f.name,data:reader.result,type:f.type});reader.readAsDataURL(f)}}/></Field>{file&&<p className="small">Selected: {file.name}</p>}<Button>Add evidence →</Button></form><div className="evidence-list">{current.evidence?.map((x:any)=><article className="evidence-item" key={x.id}>{x.file&&<img src={x.file.data} alt={'Evidence screenshot: '+x.note}/>}<div><h3>{x.note}</h3>{x.url&&<a href={x.url} target="_blank" rel="noreferrer">Open supplied source ↗</a>}<p className="small">Added {when(x.addedAt)} · Incident date: {x.date||'not specified'}</p><button className="text-button" onClick={()=>update({evidence:current.evidence.filter((e:any)=>e.id!==x.id),draftStale:true},'Evidence removed from case.')}>Remove from case</button></div></article>)}</div>{!current.evidence?.length&&<p className="empty-inline">Your saved evidence will appear here. Dates you add are recorded as supplied, not independently established.</p>}</>}
function Official({current}:any){if(!current.platform&&![kinds[0],kinds[1]].includes(current.kind))return <Note>Use the source-owner request for exposed information, or identify the relevant platform before choosing its official route. Strikeout does not invent a reporting destination.</Note>;const platform=current.platform||'Instagram',route=routes[platform]||routes.Instagram;return <div className="official-route"><span className="pixel-label">OFFICIAL NEXT STEP</span><div><h3>{current.kind===kinds[0]?'Recover through '+platform:'Report through '+platform}</h3><p>{current.kind===kinds[0]?'Use the official recovery route. Strikeout will not ask for your third-party password or recover the account for you.':'Review your facts and prepare a draft here. Submit it yourself on the official platform.'}</p></div><a className="button secondary" href={current.kind===kinds[0]?route.recovery:route.report} target="_blank" rel="noreferrer">Open official guidance ↗</a></div>}
function Inspection({current,update,source,getSource,run,busy,go,setNotice}:any){const [selected,setSelected]=useState(['portfolio','resume','external']),[approval,setApproval]=useState(false),[editor,setEditor]=useState(false),[demoNumber,setDemoNumber]=useState('+1 (202) 555-0147'),[stage,setStage]=useState('');return <section className="inspection"><div className="section-title"><span className="eyebrow">CONTROLLED PUBLIC SOURCES</span><h2>What’s actually out there?</h2><p>Read the published portfolio, résumé and selected independent copy. Supported checks cover text and contact QR codes.</p></div><div className="paper"><div className="source-options">{['portfolio','resume','external'].map(s=><label className="check" key={s}><input type="checkbox" checked={selected.includes(s)} onChange={e=>{setSelected(e.target.checked?[...selected,s]:selected.filter(x=>x!==s));setApproval(false)}}/>{s==='portfolio'?'Public portfolio':s==='resume'?'Published résumé + contact QR':'Independent copy (simulated external)'}</label>)}</div><p className="small">Only these allowlisted demo sources are fetched. The supplied phone number is compared locally in your browser. No broad internet search or AI is used.</p><label className="check"><input type="checkbox" checked={approval} onChange={e=>setApproval(e.target.checked)}/>Inspect these sources for my supplied number. I understand a match does not establish identity.</label><Button disabled={!!busy||!approval||!selected.length||!current.phone} onClick={()=>run('Reading published sources',async()=>{const s=await getSource(),out=await inspect(s,current.phone,current.country||'US',selected,setStage);const previous=current.scan?.findings||[];out.findings=out.findings.map((f:any)=>({...f,review:previous.find((p:any)=>p.id===f.id&&p.excerpt===f.excerpt&&p.source===f.source)?.review||'pending'}));update({scan:out,preview:null,verification:null},'Supported public-source inspection completed.');setNotice('Inspection finished. Review each finding before choosing an action.');})}>{busy?stage||'Inspecting…':'Inspect selected sources →'}</Button>{!current.phone&&<p className="small">Add the number to protect in Your story, or open Mira’s sample case.</p>}<details className="source-editor" open={editor} onToggle={e=>setEditor(e.currentTarget.open)}><summary>Demonstration source controls</summary><p>Change the actual public source before scanning. Only reserved fictional numbers can be published.</p><input aria-label="Fictional demo number" value={demoNumber} onChange={e=>setDemoNumber(e.target.value)}/><Button secondary disabled={!!busy} onClick={()=>run('Updating fictional source',async()=>{await api('/api/source','PATCH',{phone:demoNumber});const s=await getSource();update({phone:demoNumber,country:'US',email:s.profile.email,scan:null,preview:null,verification:null},'Fictional source number changed. New inspection required.');})}>Update source and case number</Button><Button secondary disabled={!!busy} onClick={()=>{if(confirm('Restore fictional exposure in this demo source? Previous verification will become stale.'))run('Resetting demo',async()=>{await api('/api/source/reset','POST');const s=await getSource();update({phone:s.profile.phone,country:'US',email:s.profile.email,scan:null,preview:null,verification:null},'Demo sources restored. Previous checks are stale.');})}}>Reset demo source</Button></details></div>{current.scan&&<><div className="scan-heading"><h3>{current.scan.findings.length} observed matching occurrence{current.scan.findings.length!==1?'s':''}</h3><small>Checked {when(current.scan.checkedAt)}</small></div>{current.scan.results.map((r:any)=><div className={'check-line '+(r.status==='incomplete'?'incomplete':'')} key={r.kind}><span>{r.kind}</span><strong>{r.status==='incomplete'?'Could not complete check':r.phonePresent?'Number observed':'No number found in supported checks'}</strong>{r.error&&<p>{r.error}</p>}</div>)}<div className="findings">{current.scan.findings.map((f:any)=><article key={f.id} className={'finding review-'+f.review}><div className="finding-top"><span className="eyebrow">{f.location}</span><span className="badge">{f.id==='external'?'Request only':'Repair supported'}</span></div><a href={f.source} target="_blank" rel="noreferrer">Open actual source ↗</a><pre>{f.excerpt}</pre><p className="small">{f.confidence}</p><p className="small">Potential impact: medium. A contact number may enable unwanted contact; context and intent remain unverified.</p><div className="finding-decisions">{[['confirmed','This is me · help remove'],['rejected','This is not me'],['unsure','I’m not sure'],['public','I want this public']].map(([v,l])=><button aria-pressed={f.review===v} className={f.review===v?'chosen':''} key={v} onClick={()=>update({scan:{...current.scan,findings:current.scan.findings.map((x:any)=>x.id===f.id?{...x,review:v}:x)},preview:null},'Finding reviewed: '+f.location+' — '+v)}>{l}</button>)}</div><button className="text-button" onClick={()=>update({evidence:[...(current.evidence||[]),{id:uid(),note:f.location+': '+f.excerpt,url:location.origin+f.source,addedAt:f.checkedAt}],draftStale:true},'Source-linked finding saved as evidence.')}>Save finding as evidence →</button></article>)}</div><Button onClick={()=>go('/case/'+current.id+'/requests')}>Review repairs and requests →</Button></>}</section>}
function Requests({current,update,heading,run,busy,source,getSource,go,setNotice}:any){const confirmed=current.scan?.findings.filter((f:any)=>f.review==='confirmed'&&f.id!=='external')||[];const [approved,setApproved]=useState(false),[includeEmail,setIncludeEmail]=useState(false),[includePhone,setIncludePhone]=useState(false),[evidenceIds,setEvidenceIds]=useState<string[]>([]),[request,setRequest]=useState(''),[copied,setCopied]=useState(false);const purpose=current.kind===kinds[0]?'Request for account recovery assistance':current.kind===kinds[1]?'Request to review reported impersonation':current.kind===kinds[2]?'Request to remove exposed personal contact information':current.kind===kinds[3]?'Request to review a suspicious message or link':'Request for guidance about an online incident';const defaultDraft=()=>`Subject: ${purpose}\n\nPlatform: ${current.platform||'Not specified'}\nAccount / source reference: ${current.profile||current.sourceUrl||current.link||'[not supplied]'}\nMy real profile: ${current.realProfile||'[not supplied]'}\nDate noticed: ${current.date||'Not specified'}\n\nMy account of what happened:\n${current.summary??current.description}\n\nRequested help: ${purpose}. The details above are user-supplied and have not been independently verified.\n${includeEmail?'\nReply contact: '+current.email:''}${includePhone?'\nPersonal phone: '+current.phone:''}\nSelected evidence:\n${(current.evidence||[]).filter((x:any)=>evidenceIds.includes(x.id)).map((x:any)=>'- '+x.note+(x.url?' — '+x.url:'')+(x.file?' [screenshot: '+x.file.name+']':'')).join('\n')||'No evidence selected.'}`;const draft=current.reportDraft||'';return <>{heading('04 / REQUESTS','Review first. Then decide.','Publication and reporting are separate actions. Each needs your review.')}<section className="repair-section"><div className="section-title"><span className="eyebrow">REPAIR YOUR SUPPORTED MATERIAL</span><h2>Keep the work.<br/><em>Lose the number.</em></h2></div><p>{confirmed.length} confirmed owned occurrence{confirmed.length!==1?'s':''} selected for repair. Rejected, unsure and intentionally public occurrences stay untouched.</p><Button secondary disabled={!!busy||!confirmed.length} onClick={()=>run('Preparing exact repair',async()=>{const s=await getSource();if(current.email&&current.email!==s.profile.email)throw Error('The controlled source contains '+s.profile.email+'. Review the actual work email to preserve in Your story before approving a repair.');const p=await api('/api/repair/preview','POST',{number:current.phone,country:current.country||'US',fields:confirmed.map((x:any)=>x.id),revision:current.scan.revision});update({preview:p},'Repair preview prepared. Nothing published.');setApproved(false)})}>Preview repair →</Button>{!confirmed.length&&<p className="small">Confirm the owned occurrences in Next steps first.</p>}{current.preview&&<><div className="repair-preview"><div><span className="eyebrow">BEFORE / CURRENT PUBLIC MATERIAL</span><h3>{current.preview.before.name}</h3><p>{current.preview.before.email}</p>{current.preview.fields.map((f:string)=><div className="changed-field before" key={f}><small>{f.replace(/([A-Z])/g,' $1')}</small><span>{current.preview.before[f]}</span></div>)}<ul>{current.preview.before.projects.map((p:any)=><li key={p.title}>{p.title}</li>)}</ul></div><div><span className="eyebrow">AFTER / PROPOSED REPLACEMENT</span><h3>{current.preview.after.name}</h3><p>{current.preview.after.email} <span className="preserved">retained</span></p>{current.preview.fields.map((f:string)=><div className="changed-field after" key={f}><small>{f.replace(/([A-Z])/g,' $1')}</small><span>Personal number removed</span></div>)}<ul>{current.preview.after.projects.map((p:any)=><li key={p.title}>{p.title} <span className="preserved">retained</span></li>)}</ul></div></div><p className="small">Contact QR codes are regenerated with the work email and any retained fields. The résumé is regenerated from the supported template.</p><div className="toolbar"><a className="button secondary" href={'/api/repair/'+current.preview.id+'/resume'} target="_blank" rel="noreferrer">Review repaired résumé ↗</a><a className="text-button" href={'/api/repair/'+current.preview.id+'/resume'} download="repaired-resume.pdf">Download repaired résumé ↓</a></div><Note>Downloading a clean file does not change the old public copy.</Note><label className="check"><input type="checkbox" checked={approved} onChange={e=>setApproved(e.target.checked)}/>I approve these exact changes to my controlled portfolio and résumé. Keep the work email and projects.</label><Button disabled={!approved||!!busy} onClick={()=>run('Publishing approved repair',async()=>{const result=await api('/api/repair/publish','POST',{previewId:current.preview.id,approved:true});update({publication:result,preview:null,verification:null},'Approved replacement published. Fresh verification still required.');setNotice('Published. Open the public result and run a fresh check.');go('/case/'+current.id+'/progress')})}>Approve and publish →</Button></>}</section><section className="report-section"><div className="section-title"><span className="eyebrow">{current.kind===kinds[0]?'ACCOUNT RECOVERY / REVIEWED REQUEST':current.kind===kinds[1]?'IMPERSONATION / PLATFORM REQUEST':'REVIEWED INCIDENT REQUEST'}</span><h2>A draft you control.</h2></div><Official current={current}/>{!current.reviewed&&<Note>Review your incident summary in Your story before preparing a ready-to-use report.</Note>}<div className="report-grid"><div><h3>Included information</h3><p className="small">Summary, profile references and supplied date. Missing facts remain explicitly missing.</p><label className="check"><input type="checkbox" checked={includeEmail} onChange={e=>{setIncludeEmail(e.target.checked);update({reportReady:false,draftStale:true})}}/>Include work email</label><label className="check"><input type="checkbox" checked={includePhone} onChange={e=>{setIncludePhone(e.target.checked);update({reportReady:false,draftStale:true})}}/>Include personal number</label><h4>Selected evidence</h4>{current.evidence?.map((x:any)=><label className="check" key={x.id}><input type="checkbox" checked={evidenceIds.includes(x.id)} onChange={e=>setEvidenceIds(e.target.checked?[...evidenceIds,x.id]:evidenceIds.filter(id=>id!==x.id))}/>{x.note.slice(0,90)}{x.file?' · screenshot available':''}</label>)}<Button secondary disabled={!current.reviewed} onClick={()=>update({reportDraft:defaultDraft(),reportEvidence:evidenceIds,draftStale:false,reportReady:false},'Report draft generated from reviewed facts and selected evidence.')}>Generate / regenerate draft</Button><p className="small">Selections above take effect when you regenerate. Review the actual draft before copying.</p></div><div>{current.draftStale&&<Note>Case facts or evidence changed. Regenerate and review this draft.</Note>}<Field label="Exact editable report text"><textarea rows={15} value={draft} onChange={e=>update({reportDraft:e.target.value,reportReady:false})}/></Field><label className="check"><input type="checkbox" checked={!!current.reportReady} disabled={!draft||current.draftStale} onChange={e=>update({reportReady:e.target.checked})}/>I reviewed this exact text and its selected evidence.</label><div className="toolbar"><Button secondary disabled={!current.reportReady} onClick={()=>run('Copying reviewed draft',async()=>{await navigator.clipboard.writeText(draft);setCopied(true)})}>{copied?'Copied':'Copy draft'}</Button><Button secondary disabled={!current.reportReady} onClick={()=>download('strikeout-report.txt',draft)}>Download text</Button></div>{(current.evidence||[]).filter((e:any)=>(current.reportEvidence||[]).includes(e.id)&&e.file).map((e:any)=><a className="text-button" key={e.id} href={e.file.data} download={e.file.name}>Download selected screenshot: {e.file.name} ↓</a>)}<Button secondary disabled={!current.reportReady} onClick={()=>update({reportSubmission:{at:new Date().toISOString(),draft,reference:request},reportReady:false},'User recorded platform submission. Outcome pending.')}>I submitted this myself</Button><Field label="Optional submission reference"><input value={request} onChange={e=>setRequest(e.target.value)}/></Field>{current.reportSubmission&&<Note>Submission recorded by you at {when(current.reportSubmission.at)}. Outcome pending; this is not proof of removal.</Note>}</div></div></section><section className="external-request"><span className="eyebrow">EXTERNAL COPY / REQUEST ONLY</span><h2>Another copy needs its owner.</h2><p>Strikeout cannot edit the independent archive. Prepare a request; record submission separately.</p><Field label="Editable removal request"><textarea rows={6} value={current.removalDraft??`Please remove my personal phone number from the following page: ${current.scan?.findings.find((f:any)=>f.id==='external')?.source||'[source URL]'}\n\nThe contact detail appears in the archived contact field. Please preserve the other useful event information. Let me know when the published source has changed.\n\nThis is a fictional demonstration request.`} onChange={e=>update({removalDraft:e.target.value})}/></Field><Button secondary onClick={()=>{const el=document.querySelector('.external-request textarea') as HTMLTextAreaElement;download('removal-request.txt',el.value)}}>Download request</Button><Button secondary onClick={()=>update({removalSubmitted:new Date().toISOString()},'User recorded external removal-request submission. Copy remains unresolved.')}>Record manual submission</Button>{current.removalSubmitted&&<p>Request recorded. The source remains unresolved until a supported recheck establishes a change.</p>}</section></>}
function Progress({current,update,heading,run,busy,getSource,go}:any){const [stage,setStage]=useState('');return <>{heading('05 / PROGRESS','What changed. What didn’t.','An action recorded is different from an outcome checked.')}<div className="publication-summary"><span className="pixel-label">PUBLICATION</span><h2>{current.publication?'Replacement published.':'No repair published yet.'}</h2><p>{current.publication?'The save response is not our evidence. Fetch the actual public files again.':'Review findings and approve an exact repair before publishing.'}</p><div className="toolbar"><Button disabled={!!busy||!current.phone} onClick={()=>run('Checking public copies',async()=>{const s=await getSource(),out=await inspect(s,current.phone,current.country||'US',['portfolio','resume','external'],setStage);out.passed=out.results.filter((r:any)=>r.kind!=='external').every((r:any)=>r.status==='complete'&&!r.phonePresent&&r.emailRetained&&r.projectsRetained&&Number(r.revision)===s.profile.revision);update({verification:out},'Fresh public-source verification '+(out.passed?'passed for supported owned sources.':'did not establish a complete owned-source repair.'));})}>{busy?stage||'Checking…':'Check published copy →'}</Button><Button secondary onClick={()=>run('Opening published material',async()=>{const s=await getSource();window.open(s.base+'/portfolio','_blank','noopener')})}>Open actual portfolio ↗</Button><Button secondary onClick={()=>run('Opening résumé',async()=>{const s=await getSource();window.open(s.base+'/resume.pdf','_blank','noopener')})}>Open actual résumé ↗</Button></div></div>{current.verification&&<section className="verification"><div className={'verification-verdict '+(current.verification.passed?'passed':'partial')}><Pop state={current.verification.passed?'celebrating':'concerned'} size={80}/><div><h2>{current.verification.passed?'Supported owned sources checked.':'Some checks remain unresolved.'}</h2><p>{current.verification.passed?'The supplied number was not found by the supported text and QR checks. Work email and project content remain.':'Read each source result below. Incomplete checks never count as removal.'}</p><small>{when(current.verification.checkedAt)} · Specific sources only</small></div></div>{current.verification.results.map((r:any)=><article className="verification-row" key={r.kind}><div><h3>{r.kind==='external'?'Independent copy':r.kind==='resume'?'Published résumé':'Public portfolio'}</h3><a href={r.url} target="_blank" rel="noreferrer">Inspect source ↗</a></div><div><strong>{r.status==='incomplete'?'Could not verify':r.phonePresent?'Number still present':r.kind==='external'?'Not found in checked source':'Number absent in supported checks'}</strong><p>{r.error|| (r.kind==='external'?'This copy is independent of the repair.':`Contact QR ${r.qrDecoded?'decoded':'incomplete'} · work email ${r.emailRetained?'retained':'not confirmed'} · projects ${r.projectsRetained?'retained':'not confirmed'}`)}</p></div></article>)}</section>}<div className="progress-grid"><section><h2>Case activity</h2><ol className="timeline">{[...(current.timeline||[])].reverse().map((x:any)=><li key={x.id}><time>{when(x.at)}</time><p>{x.text}</p></li>)}</ol></section><aside className="paper"><h3>A useful follow-up.</h3><Field label="Follow-up date"><input type="date" value={current.followUp||''} onChange={e=>update({followUp:e.target.value})}/></Field><p className="small">Saved in this case. No background notification is sent.</p><h3>Human support</h3><p>Some things deserve another person.</p><a href="https://aarambhindia.org/meri-trustline-6363176363-indias-bharosemand-helpline-for-reporting-online-risks/" target="_blank" rel="noreferrer">Meri Trustline · online-harm support ↗</a><br/><a href="https://icallhelpline.org/" target="_blank" rel="noreferrer">iCALL · counselling information ↗</a><p className="small">Check each service’s current availability and eligibility.</p><Button secondary onClick={()=>download('strikeout-case.json',JSON.stringify(current,null,2),'application/json')}>Export this case ↓</Button></aside></div></>}
function Discovery({heading,authenticated,ids,setIds,go,sample,cases,save,run,busy}:any){const [type,setType]=useState('GitHub'),[value,setValue]=useState(''),[label,setLabel]=useState(''),[selected,setSelected]=useState<string[]>([]),[approved,setApproved]=useState(false),[results,setResults]=useState<any>(null),[reviews,setReviews]=useState<any>({});return <section className="page-wrap">{heading('CHECK MY EXPOSURE','Public doesn’t mean obvious.','Choose your own identifiers, review where they will go, and decide what each result means.')}<div className="discovery-grid"><section><form className="paper" onSubmit={e=>{e.preventDefault();setIds([...ids,{id:uid(),type,value,label}]);setValue('');setLabel('');setApproved(false)}}><h2>Your identifiers</h2><div className="field-pair"><Field label="Type"><select value={type} onChange={e=>setType(e.target.value)}>{['GitHub','Instagram','Facebook','Email','Phone','Name / alias'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Label (optional)"><input value={label} onChange={e=>setLabel(e.target.value)} placeholder="Work profile"/></Field></div><Field label={type==='GitHub'?'Your GitHub username':'Identifier'}><input required maxLength={200} value={value} onChange={e=>setValue(e.target.value)}/></Field><Button secondary>Add identifier</Button><p className="small">Entering an identifier does not verify ownership. Use this tool only for your own information.</p></form><div className="identifier-list">{ids.map((x:any)=><div key={x.id}><label className="check"><input type="checkbox" disabled={x.type!=='GitHub'} checked={selected.includes(x.id)} onChange={e=>{setSelected(e.target.checked?[...selected,x.id]:selected.filter(id=>id!==x.id));setApproved(false)}}/><span><strong>{x.label||x.value}</strong><small>{x.type} · {x.value}</small>{x.type!=='GitHub'&&<small>No live provider connected for this identifier type.</small>}</span></label><button className="text-button" onClick={()=>{const v=prompt('Edit this identifier',x.value);if(v?.trim()){setIds(ids.map((y:any)=>y.id===x.id?{...y,value:v.trim()}:y));setApproved(false)}}}>Edit</button><button className="text-button" onClick={()=>{setIds(ids.filter((y:any)=>y.id!==x.id));setSelected(selected.filter(id=>id!==x.id));setApproved(false)}}>Remove</button></div>)}</div></section><aside className="paper consent-panel"><span className="eyebrow">BEFORE YOU SEARCH</span><h2>You choose what goes.</h2><p><strong>Provider:</strong> GitHub public profile API.</p><p><strong>Sent:</strong> selected GitHub usernames only.</p><p><strong>Not queried:</strong> private profiles, platform-wide content, emails, phone databases or leaked credentials.</p><div className="consent-values">{ids.filter((x:any)=>selected.includes(x.id)).map((x:any)=><code key={x.id}>{x.value}</code>)}</div><label className="check"><input type="checkbox" checked={approved} onChange={e=>setApproved(e.target.checked)}/>These are my identifiers. I approve sending the selected usernames to GitHub for this check.</label><Button disabled={!approved||!selected.length||!!busy} onClick={()=>authenticated(async()=>run('Checking GitHub public profiles',async()=>{const out=[];for(const id of selected){const x=ids.find((x:any)=>x.id===id);try{out.push(await api('/api/search/github','POST',{username:x.value,approved:true}));}catch(e:any){out.push({provider:'GitHub',status:'failed',error:e.message,findings:[]})}}setResults(out)}))}>Check selected identifiers →</Button><p className="small">A public profile is not proof of harm. Exact username matching does not prove it belongs to you.</p></aside></div><div className="discovery-results">{results?.map((r:any,i:number)=><section key={i}><h2>{r.provider}</h2>{r.status==='failed'?<Note tone="error">Check failed: {r.error}</Note>:!r.findings.length?<Note>Nothing found in this checked provider. This is not an assessment of your overall safety.</Note>:r.findings.map((f:any)=><article className="finding" key={f.id}><div className="finding-top"><a href={f.url} target="_blank" rel="noreferrer">{f.source} ↗</a><span className="badge">Potential impact: {f.severity}</span></div><p className="source-excerpt">{f.excerpt}</p><p><strong>Match:</strong> {f.confidence}</p><p>{f.reason}</p><small>Retrieved {when(r.checkedAt)}</small><div className="finding-decisions">{['This is me','This is not me','I’m not sure','I want this public','I want help removing this'].map(v=><button className={reviews[f.id]===v?'chosen':''} key={v} onClick={()=>setReviews({...reviews,[f.id]:v})}>{v}</button>)}</div><Button secondary onClick={()=>{const at=new Date().toISOString(),c={id:uid(),title:'Public profile review',kind:kinds[2],description:f.excerpt,summary:'A public GitHub profile was returned for my supplied username. Ownership and desired visibility need my review.',reviewed:false,createdAt:at,evidence:[{id:uid(),note:f.excerpt,url:f.url,addedAt:r.checkedAt}],timeline:[{id:uid(),at,text:'Retrieved public profile saved as evidence; identity not established.'}]};save(c);go('/case/'+c.id+'/story')}}>Create case with this evidence →</Button>{cases.length>0&&<Button secondary onClick={()=>{const c=cases[0];save({...c,evidence:[...(c.evidence||[]),{id:uid(),note:f.excerpt,url:f.url,addedAt:r.checkedAt}],draftStale:true,timeline:[...(c.timeline||[]),{id:uid(),at:new Date().toISOString(),text:'Reviewed public-source finding attached as evidence.'}]});go('/case/'+c.id+'/evidence')}}>Attach to latest case →</Button>}</article>)}</section>)}</div><div className="sample-callout"><Pop size={90} state="curious"/><div><h2>Want to see an actual repair?</h2><p>Explore a separately labelled fictional portfolio, résumé and QR-code case.</p></div><Button secondary onClick={sample}>Explore sample case →</Button></div></section>}
function AiPanel({current,close,authenticated}:any){const [context,setContext]=useState(current?.summary||''),[task,setTask]=useState('Explain the next useful step using only these notes.'),[approved,setApproved]=useState(false),[busy,setBusy]=useState(false),[answer,setAnswer]=useState(''),[error,setError]=useState('');return <div className="assistant-panel" role="dialog" aria-label="Pop assistant"><button className="modal-close" aria-label="Close Pop" onClick={close}>×</button><div className="assistant-title"><Pop size={70} state={busy?'inspecting':'curious'}/><div><span className="eyebrow">POP / SECOND PAIR OF EYES</span><h2>One thing at a time.</h2></div></div><Field label="What would you like help with?"><input value={task} onChange={e=>{setTask(e.target.value);setApproved(false)}}/></Field><Field label="Exact context to share with Google Gemini"><textarea rows={5} value={context} onChange={e=>{setContext(e.target.value);setApproved(false)}}/></Field><p className="small">Remove anything unnecessary. Screenshots, passwords and unrelated cases are not attached. Provider data policies apply.</p><label className="check"><input type="checkbox" checked={approved} onChange={e=>setApproved(e.target.checked)}/>I approve sending this selected text for a wording suggestion.</label><Button disabled={!approved||!context||busy} onClick={()=>authenticated(async()=>{setBusy(true);setError('');try{const x=await api('/api/ai','POST',{task,context,approved:true});setAnswer(x.text)}catch(e:any){setError(e.message)}finally{setBusy(false)}})}>{busy?'Pop is reading your selected notes…':'Ask Pop →'}</Button>{error&&<Note tone="error">{error}</Note>}{answer&&<div className="ai-answer"><span className="eyebrow">SUGGESTION / REVIEW BEFORE USING</span><p>{answer}</p><button className="text-button" onClick={()=>navigator.clipboard.writeText(answer)}>Copy suggestion</button></div>}<p className="small">Pop suggests wording. You decide what enters your case. All core tools work without AI.</p></div>}
function LinkCheck({current}:any){const [url,setUrl]=useState(current.link||''),[label,setLabel]=useState(''),[results,setResults]=useState<any>(null),[error,setError]=useState('');return <section className="paper"><span className="eyebrow">LOCAL SIGNALS / NO DESTINATION VISITED</span><h2>Take a closer look.</h2><Field label="Visible link label (optional)"><input value={label} onChange={e=>setLabel(e.target.value)}/></Field><Field label="Actual destination"><input value={url} onChange={e=>setUrl(e.target.value)}/></Field><Button secondary onClick={async()=>{try{setResults(await api('/api/link','POST',{label,destination:url}));setError('')}catch(e:any){setError(e.message)}}}>Inspect link →</Button>{error&&<Note tone="error">{error}</Note>}{results?.signals.map((x:any)=><Note key={x.signal}><strong>{x.signal}</strong><p>{x.explanation}</p></Note>)}</section>}
createRoot(document.getElementById('root')!).render(<App/>);
